workflows..github/workflows/deploy-runtime.yml:
name: SPLRAD Steward / Deploy Runtime

on:
  push:
    paths:
      - ".github/workflows/deploy-runtime.yml"
      - "scripts/verify-workflows.mjs"
      - "packages/runtime/**"
      - "packages/core/**"
      - "packages/github/**"
      - "packages/runner/**"
      - "config/**"
      - "schema/**"
      - "package.json"
      - "package-lock.json"
  workflow_dispatch:

permissions:
  contents: read

jobs:
  deploy:
    if: github.event_name == 'workflow_dispatch' || github.ref == format('refs/heads/{0}', github.event.repository.default_branch)
    runs-on: ubuntu-latest
    timeout-minutes: 20
    environment:
      name: steward-deployment
      deployment: true
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1
        with: { ref: "${{ github.sha }}", persist-credentials: false }
      - uses: actions/setup-node@820762786026740c76f36085b0efc47a31fe5020
        with: { node-version-file: .node-version, cache: npm }
      - run: npm ci --ignore-scripts
      - run: npm test
      - run: npm run typecheck
      - run: npm run verify:dist
      - run: npm run verify:workflows
      - name: 列出并应用D1迁移
        shell: bash
        env:
          CLOUDFLARE_API_TOKEN: ${{ secrets.CLOUDFLARE_API_TOKEN }}
        run: |
          set -euo pipefail
          npx wrangler d1 migrations list splrad-steward-issue-snapshots --remote --config packages/runtime/wrangler.toml
          npx wrangler d1 migrations apply splrad-steward-issue-snapshots --remote --config packages/runtime/wrangler.toml
      - name: 部署中央运行程序
        id: deploy
        shell: bash
        env:
          CLOUDFLARE_API_TOKEN: ${{ secrets.CLOUDFLARE_API_TOKEN }}
        run: |
          set -euo pipefail
          deployment_log="$(mktemp)"
          trap 'rm -f "$deployment_log"' EXIT
          set +e
          npx wrangler deploy --config packages/runtime/wrangler.toml --var POLICY_SHA:${{ github.sha }} 2>&1 | tee "$deployment_log"
          deploy_status="${PIPESTATUS[0]}"
          set -e
          if [[ "$deploy_status" -ne 0 ]]; then
            exit "$deploy_status"
          fi
          runtime_url="$(grep -Eo 'https://[^[:space:]]+\.workers\.dev' "$deployment_log" | tail -n 1 || true)"
          if [[ -z "$runtime_url" ]]; then
            echo '部署输出中没有运行程序网址。' >&2
            exit 1
          fi
          printf 'runtime_url=%s\n' "$runtime_url" >> "$GITHUB_OUTPUT"
      - name: 复核运行程序健康状态
        shell: bash
        env:
          RUNTIME_URL: ${{ steps.deploy.outputs.runtime_url }}
          EXPECTED_POLICY_SHA: ${{ github.sha }}
        run: |
          node --input-type=module <<'NODE'
          const expectedKeys = ["appId", "organizationId", "policySha", "secretsReady", "status", "version"];
          const deadline = Date.now() + 60_000;
          let attempt = 0;
          let verifiedBody;
          let lastFailure = "尚未请求健康接口";
          while (Date.now() < deadline) {
            attempt += 1;
            try {
              const remaining = Math.max(1, deadline - Date.now());
              const response = await fetch(`${process.env.RUNTIME_URL}/health`, {
                headers: { accept: "application/json" },
                signal: AbortSignal.timeout(Math.min(10_000, remaining)),
              });
              if (!response.ok) {
                await response.body?.cancel();
                lastFailure = `健康接口返回HTTP ${response.status}`;
              } else {
                const body = await response.json();
                const failures = [];
                if (JSON.stringify(Object.keys(body).sort()) !== JSON.stringify(expectedKeys)) failures.push("字段集合尚未匹配");
                if (body.status !== "ok") failures.push("状态尚未匹配");
                if (body.policySha !== process.env.EXPECTED_POLICY_SHA) failures.push("规则提交尚未传播");
                if (body.organizationId !== 302208797) failures.push("组织编号尚未匹配");
                if (body.appId !== 4243096) failures.push("应用编号尚未匹配");
                if (body.secretsReady !== true) failures.push("运行时密钥尚未齐备");
                if (typeof body.version !== "string" || !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/iu.test(body.version)) failures.push("Cloudflare版本编号尚未匹配");
                if (failures.length === 0) {
                  verifiedBody = body;
                  break;
                }
                lastFailure = failures.join("；");
              }
            } catch (error) {
              lastFailure = error instanceof Error ? error.message : "未知网络错误";
            }
            console.log(JSON.stringify({ status: "waiting", attempt, reason: lastFailure }));
            const pause = Math.min(2_000, Math.max(0, deadline - Date.now()));
            if (pause > 0) await new Promise(resolve => setTimeout(resolve, pause));
          }
          if (!verifiedBody) throw new Error(`健康复核在60秒内未收敛：${lastFailure}`);
          console.log(JSON.stringify({ status: verifiedBody.status, policySha: verifiedBody.policySha, version: verifiedBody.version, organizationId: verifiedBody.organizationId, appId: verifiedBody.appId, secretsReady: verifiedBody.secretsReady }));
          NODE

workflows..github/workflows/native-review.yml:
name: SPLRAD Steward / Native Review

on:
  workflow_dispatch:
    inputs:
      deliveryId: { required: true, type: string }
      repositoryId: { required: true, type: string }
      eventAfterSha: { required: true, type: string }
      policySha: { required: true, type: string }
      pullRequestNumber: { required: false, type: string }
      observeOnly: { description: 仅观察审查状态, required: false, type: boolean, default: false }

permissions:
  contents: read
concurrency:
  group: steward-pr-body-${{ inputs.repositoryId }}
  cancel-in-progress: false
  queue: max

jobs:
  request:
    if: inputs.observeOnly != true && inputs.pullRequestNumber != '' && github.actor_id == '301115370' && github.repository == 'splrad/steward' && github.ref == format('refs/heads/{0}', github.event.repository.default_branch)
    runs-on: ubuntu-latest
    timeout-minutes: 5
    environment:
      name: steward-automation
      deployment: false
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1
        with: { ref: "${{ github.workflow_sha }}", persist-credentials: false }
      - uses: actions/setup-node@820762786026740c76f36085b0efc47a31fe5020
        with: { node-version-file: .node-version, cache: npm }
      - run: npm ci --ignore-scripts
      - name: 解析审查触发模式
        id: review_policy
        shell: bash
        env:
          APP_ID: "4243096"
          INSTALLATION_ID: "145952003"
          STEWARD_APP_PRIVATE_KEY: ${{ secrets.STEWARD_APP_PRIVATE_KEY }}
          REPOSITORY_ID: ${{ inputs.repositoryId }}
          POLICY_SHA: ${{ github.workflow_sha }}
        run: node packages/runner/dist/index.js review-trigger-mode --repository-id "$REPOSITORY_ID" --policy-sha "$POLICY_SHA"
      - name: 请求并核对Copilot审查
        shell: bash
        env:
          APP_ID: "4243096"
          INSTALLATION_ID: "145952003"
          STEWARD_APP_PRIVATE_KEY: ${{ secrets.STEWARD_APP_PRIVATE_KEY }}
          TRIGGER_ACTOR_ID: ${{ github.actor_id }}
          WORKFLOW_REPOSITORY: ${{ github.repository }}
          WORKFLOW_EVENT: ${{ github.event_name }}
          WORKFLOW_REF: ${{ github.workflow_ref }}
          WORKFLOW_RUN_REF: ${{ github.ref }}
          WORKFLOW_DEFAULT_BRANCH: ${{ github.event.repository.default_branch }}
          WORKFLOW_SHA: ${{ github.workflow_sha }}
          DELIVERY_ID: ${{ inputs.deliveryId }}
          REPOSITORY_ID: ${{ inputs.repositoryId }}
          PULL_REQUEST_NUMBER: ${{ inputs.pullRequestNumber }}
          EVENT_HEAD_SHA: ${{ inputs.eventAfterSha }}
          POLICY_SHA: ${{ github.workflow_sha }}
        run: |
          review_arguments=(
            --delivery-id "$DELIVERY_ID"
            --repository-id "$REPOSITORY_ID"
            --pull-request-number "$PULL_REQUEST_NUMBER"
            --event-head-sha "$EVENT_HEAD_SHA"
            --policy-sha "$POLICY_SHA"
          )
          node packages/runner/dist/index.js request-copilot-review "${review_arguments[@]}"

  observe:
    if: inputs.observeOnly == true && github.event_name == 'workflow_dispatch' && github.repository == 'splrad/steward' && github.ref == format('refs/heads/{0}', github.event.repository.default_branch)
    runs-on: ubuntu-latest
    timeout-minutes: 5
    environment:
      name: steward-automation
      deployment: false
    outputs:
      state: ${{ steps.observe.outputs.state }}
      reason: ${{ steps.observe.outputs.reason }}
      headSha: ${{ steps.observe.outputs.headSha }}
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1
        with:
          ref: ${{ github.workflow_sha }}
          persist-credentials: false
      - uses: actions/setup-node@820762786026740c76f36085b0efc47a31fe5020
        with:
          node-version-file: .node-version
          cache: npm
      - run: npm ci --ignore-scripts
      - name: 读取当前Copilot审查证据
        id: observe
        shell: bash
        env:
          APP_ID: "4243096"
          INSTALLATION_ID: "145952003"
          STEWARD_APP_PRIVATE_KEY: ${{ secrets.STEWARD_APP_PRIVATE_KEY }}
          REPOSITORY_ID: ${{ inputs.repositoryId }}
          PULL_REQUEST_NUMBER: ${{ inputs.pullRequestNumber }}
          HEAD_SHA: ${{ inputs.eventAfterSha }}
          POLICY_SHA: ${{ github.workflow_sha }}
        run: |
          node packages/runner/dist/index.js observe-copilot-review \
            --repository-id "$REPOSITORY_ID" \
            --pull-request-number "$PULL_REQUEST_NUMBER" \
            --event-head-sha "$HEAD_SHA" \
            --policy-sha "$POLICY_SHA"

