name: SPLRAD Steward / Product Build
run-name: 'product-build:${{ inputs.repositoryId }}:${{ inputs.buildId }}'
on:
  workflow_dispatch:
    inputs:
      repositoryId: { required: true, type: string }
      buildId: { required: true, type: string }
      targetSha: { required: true, type: string }
permissions: { contents: read, actions: read }
concurrency:
  group: product-build-${{ inputs.repositoryId }}-${{ inputs.buildId }}
  cancel-in-progress: false
jobs:
  plan:
    if: github.repository_id == '1296724484' && github.ref == format('refs/heads/{0}', github.event.repository.default_branch)
    runs-on: ubuntu-latest
    timeout-minutes: 60
    environment: { name: steward-release, deployment: false }
    outputs:
      artifactId: ${{ steps.context.outputs.artifact-id }}
      runner: ${{ steps.plan.outputs.runner }}
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1
        with: { ref: "${{ github.workflow_sha }}", persist-credentials: false }
      - uses: actions/setup-node@820762786026740c76f36085b0efc47a31fe5020
        with: { node-version-file: .node-version, cache: npm }
      - run: npm ci --ignore-scripts
      - name: 固定已登记产品构建来源
        timeout-minutes: 45
        id: plan
        shell: bash
        env:
          APP_ID: "4243096"
          INSTALLATION_ID: "145952003"
          STEWARD_APP_PRIVATE_KEY: ${{ secrets.STEWARD_APP_PRIVATE_KEY }}
          RUNTIME_URL: https://splrad-steward-runtime.alearner-5ef.workers.dev
          REPOSITORY_ID: ${{ inputs.repositoryId }}
          BUILD_ID: ${{ inputs.buildId }}
          TARGET_SHA: ${{ inputs.targetSha }}
          POLICY_SHA: ${{ github.workflow_sha }}
          RUN_ID: ${{ github.run_id }}
          ATTEMPT: ${{ github.run_attempt }}
        run: node packages/runner/dist/index.js release-build --operation plan-product --repository-id "$REPOSITORY_ID" --build-id "$BUILD_ID" --target-sha "$TARGET_SHA" --policy-sha "$POLICY_SHA" --run-id "$RUN_ID" --attempt "$ATTEMPT" --output build-context
      - uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a
        id: context
        with:
          name: product-build-request-${{ github.run_attempt }}
          path: build-context
          if-no-files-found: error
          retention-days: 7
  build:
    needs: plan
    runs-on: ${{ needs.plan.outputs.runner }}
    timeout-minutes: 360
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1
        with: { ref: "${{ github.workflow_sha }}", persist-credentials: false }
      - uses: actions/setup-node@820762786026740c76f36085b0efc47a31fe5020
        with: { node-version-file: .node-version, cache: npm }
      - run: npm ci --ignore-scripts
      - uses: actions/setup-dotnet@a98b56852c35b8e3190ac28c8c2271da59106c68
        with: { dotnet-version: '10.0.402' }
      - uses: actions/download-artifact@3e5f45b2cfb9172054b4087a40e8e0b5a5461e7c
        with:
          artifact-ids: ${{ needs.plan.outputs.artifactId }}
          merge-multiple: true
          path: build-context
      - name: 无发布凭据构建产品并校验原生版本
        shell: pwsh
        env:
          POLICY_SHA: ${{ github.workflow_sha }}
          RUN_ID: ${{ github.run_id }}
        run: node packages/runner/dist/index.js release-build --operation execute-product --policy-sha "$env:POLICY_SHA" --run-id "$env:RUN_ID" --request build-context/request.json --source-bundle build-context/source.bundle --workspace product-source --assets build-assets --inspector scripts/inspect-native-release.ps1 --output artifact-manifest.json
      - uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a
        with:
          name: product-build-result-${{ github.run_attempt }}
          path: |
            build-assets
            artifact-manifest.json*
          if-no-files-found: error
          retention-days: 30

workflows..github/workflows/release-build-complete:
name: SPLRAD Steward / Release Build Completion
on:
  workflow_dispatch:
    inputs:
      runId: { required: true, type: string }
  workflow_run:
    workflows: ['SPLRAD Steward / Release Build']
    types: [completed]
permissions: { contents: read, actions: read }
concurrency:
  group: build-complete-${{ github.event.workflow_run.id || inputs.runId }}
  cancel-in-progress: false
jobs:
  accept:
    if: github.repository_id == '1296724484' && ((github.event_name == 'workflow_dispatch' && github.ref == format('refs/heads/{0}', github.event.repository.default_branch)) || (github.event.workflow_run.event == 'workflow_dispatch' && github.event.workflow_run.head_repository.id == 1296724484 && github.event.workflow_run.head_branch == github.event.repository.default_branch))
    runs-on: windows-2025
    timeout-minutes: 360
    environment: { name: steward-release, deployment: false }
    steps:
      - name: 明确阻断策略漂移的完成回调
        if: github.event_name == 'workflow_run'
        shell: pwsh
        env:
          SOURCE_POLICY: ${{ github.event.workflow_run.head_sha }}
          CURRENT_POLICY: ${{ github.workflow_sha }}
        run: |
          if ($env:SOURCE_POLICY -cne $env:CURRENT_POLICY) { throw "RELEASE_POLICY_DRIFT: synchronize deployed policy and default branch, then retry completion" }
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1
        with: { ref: "${{ github.workflow_sha }}", persist-credentials: false }
      - uses: actions/setup-node@820762786026740c76f36085b0efc47a31fe5020
        with: { node-version-file: .node-version, cache: npm }
      - run: npm ci --ignore-scripts
      - name: 回读成功或失败的绑定构建运行
        id: resolved
        shell: pwsh
        env:
          APP_ID: "4243096"
          INSTALLATION_ID: "145952003"
          STEWARD_APP_PRIVATE_KEY: ${{ secrets.STEWARD_APP_PRIVATE_KEY }}
          RUNTIME_URL: https://splrad-steward-runtime.alearner-5ef.workers.dev
          POLICY_SHA: ${{ github.workflow_sha }}
          RUN_ID: ${{ github.event.workflow_run.id || inputs.runId }}
        run: node packages/runner/dist/index.js release-build --operation resolve --policy-sha "$env:POLICY_SHA" --run-id "$env:RUN_ID"
      - uses: actions/download-artifact@3e5f45b2cfb9172054b4087a40e8e0b5a5461e7c
        if: steps.resolved.outputs.ready == 'true'
        with:
          repository: splrad/steward
          artifact-ids: ${{ steps.resolved.outputs.artifactId }}
          run-id: ${{ github.event.workflow_run.id || inputs.runId }}
          github-token: ${{ github.token }}
          merge-multiple: true
          path: seed/assets
      - name: 独立复算下载字节并接受构建
        id: accept
        if: steps.resolved.outputs.ready == 'true'
        shell: pwsh
        env:
          APP_ID: "4243096"
          INSTALLATION_ID: "145952003"
          STEWARD_APP_PRIVATE_KEY: ${{ secrets.STEWARD_APP_PRIVATE_KEY }}
          RUNTIME_URL: https://splrad-steward-runtime.alearner-5ef.workers.dev
          POLICY_SHA: ${{ github.workflow_sha }}
          RUN_ID: ${{ github.event.workflow_run.id || inputs.runId }}
          REPOSITORY_ID: ${{ steps.resolved.outputs.repositoryId }}
          TARGET_TAG: ${{ steps.resolved.outputs.tag }}
          REQUEST_KEY: ${{ steps.resolved.outputs.key }}
          ARTIFACT_ID: ${{ steps.resolved.outputs.artifactId }}
          ATTEMPT: ${{ steps.resolved.outputs.attempt }}
        run: node packages/runner/dist/index.js release-build --operation accept --policy-sha "$env:POLICY_SHA" --run-id "$env:RUN_ID" --repository-id "$env:REPOSITORY_ID" --target-tag "$env:TARGET_TAG" --request-key "$env:REQUEST_KEY" --artifact-id "$env:ARTIFACT_ID" --attempt "$env:ATTEMPT" --assets seed/assets --inspector scripts/inspect-native-release.ps1 --output seed
      - name: 为变化资产创建新候选并重新审阅
        id: revision
        if: steps.accept.outputs.reviewRequired == 'true'
        shell: pwsh
        env:
          APP_ID: "4243096"
          INSTALLATION_ID: "145952003"
          STEWARD_APP_PRIVATE_KEY: ${{ secrets.STEWARD_APP_PRIVATE_KEY }}
          RUNTIME_URL: https://splrad-steward-runtime.alearner-5ef.workers.dev
          POLICY_SHA: ${{ github.workflow_sha }}
          RUN_ID: ${{ github.event.workflow_run.id || inputs.runId }}
          REPOSITORY_ID: ${{ steps.resolved.outputs.repositoryId }}
          TARGET_TAG: ${{ steps.resolved.outputs.tag }}
          REQUEST_KEY: ${{ steps.resolved.outputs.key }}
          ARTIFACT_ID: ${{ steps.resolved.outputs.artifactId }}
          ATTEMPT: ${{ steps.resolved.outputs.attempt }}
        run: node packages/runner/dist/index.js release-candidate --operation revise-rebuild --policy-sha "$env:POLICY_SHA" --repository-id "$env:REPOSITORY_ID" --target-tag "$env:TARGET_TAG" --request-key "$env:REQUEST_KEY"
