      - name: 校验候选输入编号
        shell: bash
        env:
          BUNDLE_ARTIFACT_ID: ${{ inputs.bundleArtifactId }}
          BUNDLE_RUN_ID: ${{ inputs.bundleRunId }}
        run: '[[ "$BUNDLE_ARTIFACT_ID" =~ ^[1-9][0-9]*$ && "$BUNDLE_RUN_ID" =~ ^[1-9][0-9]*$ ]]'
      - uses: actions/download-artifact@3e5f45b2cfb9172054b4087a40e8e0b5a5461e7c
        with:
          repository: splrad/steward
          artifact-ids: ${{ inputs.bundleArtifactId }}
          run-id: ${{ inputs.bundleRunId }}
          github-token: ${{ github.token }}
          merge-multiple: true
          path: candidate-bundle
      - name: 校验并持久化候选输入
        shell: bash
        env:
          APP_ID: "4243096"
          INSTALLATION_ID: "145952003"
          STEWARD_APP_PRIVATE_KEY: ${{ secrets.STEWARD_APP_PRIVATE_KEY }}
          RUNTIME_URL: https://splrad-steward-runtime.alearner-5ef.workers.dev
          REPOSITORY_ID: ${{ inputs.repositoryId }}
          TARGET_TAG: ${{ inputs.targetTag }}
          POLICY_SHA: ${{ github.workflow_sha }}
        run: node packages/runner/dist/index.js release-candidate --operation prepare --repository-id "$REPOSITORY_ID" --target-tag "$TARGET_TAG" --policy-sha "$POLICY_SHA" --bundle candidate-bundle --assets candidate-bundle/assets

  generation-ticket:
    if: inputs.operation == 'generate' && github.repository == 'splrad/steward' && github.ref == format('refs/heads/{0}', github.event.repository.default_branch)
    runs-on: ubuntu-latest
    timeout-minutes: 60
    environment: { name: steward-release, deployment: false }
    outputs:
