          path: grant
      - uses: actions/download-artifact@3e5f45b2cfb9172054b4087a40e8e0b5a5461e7c
        with:
          repository: splrad/steward
          artifact-ids: ${{ inputs.bundleArtifactId }}
          run-id: ${{ inputs.bundleRunId }}
